#!/bin/sh

update_etc_shells() {
  # make git-shell a valid shell
  if ! grep -qe '^/usr/bin/git-shell$' etc/shells; then
    echo '/usr/bin/git-shell' >> etc/shells
  fi
}

post_install() {
  update_etc_shells
}

post_upgrade() {
  update_etc_shells
}

post_remove() {
  sed -i -r '/^\/usr\/bin\/git-shell$/d' etc/shells
}

post_install() {
  command -v update-desktop-database >/dev/null 2>&1 && update-desktop-database -q
  command -v gtk-update-icon-cache >/dev/null 2>&1 && gtk-update-icon-cache -q -t -f usr/share/icons/hicolor
}

post_upgrade() {
  post_install
}

post_remove() {
  post_install
}

post_install() {
  # Enable socket by default
  systemctl --global enable gnome-keyring-daemon.socket
}

post_upgrade() {
  if (( $(vercmp $2 1:42.0-1) < 0)); then
    systemctl --global enable gnome-keyring-daemon.socket
  fi
}

pre_remove() {
  systemctl --global disable gnome-keyring-daemon.socket
}

post_install() {
  setcap cap_sys_admin=ep usr/bin/gsr-kms-server
}

post_upgrade() {
  post_install
}

